export const DEFAULT_FILE_ICON = "document";
export const FOLDER_ICON = "folder-closed";
export const FOLDER_OPEN_ICON = "folder";

/** True when the pack has artwork under this name. */
export function hasIcon(name: string): boolean {
  return name in ICONS;
}

/** One icon from the pack, at `size` pixels. Folders and other single-colour
 * icons take `color` when given, which is how the tree keeps them in step
 * with the palette instead of the pack's fixed slate. */
export function AntigravityIcon({
  icon,
  size = 16,
  color,
}: {
  icon: string;
  size?: number;
  color?: string;
}) {
  const [glyph, own, box] = ICONS[icon] ?? ICONS[DEFAULT_FILE_ICON];
  // An empty colour slot only exists to carry a viewBox past it.
  return (
    <svg
      width={size}
      height={size}
      viewBox={box || "0 0 24 24"}
      fill="none"
      className="shrink-0"
      // `currentColor` in the artwork resolves to this; multi-colour marks
      // ignore it entirely.
      style={{ color: color ?? own }}
      aria-hidden="true"
    >
      {GLYPHS[glyph]}
    </svg>
  );
}
